package com.monitoring.agent

import java.net.{URI, URLDecoder}
import java.nio.charset.StandardCharsets
import java.util.concurrent.atomic.{AtomicBoolean, AtomicReference}
import java.util.concurrent.{CountDownLatch, Executors, TimeUnit}
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

object MonitoringAgent {
  private val shutdownRequested = new AtomicBoolean(false)
  private val currentSession = new AtomicReference[OAuthSession](null)
  private val executor = Executors.newFixedThreadPool(4)
  private val shutdownLatch = new CountDownLatch(1)

  case class OAuthSession(accessToken: String, redirectUri: String, state: String, expiresAt: Long)

  case class OAuthConfig(
    clientId: String,
    clientSecret: String,
    authorizeEndpoint: String,
    tokenEndpoint: String,
    allowedRedirectHosts: Set[String]
  )

  val config = OAuthConfig(
    clientId = "monitoring-agent-prod",
    clientSecret = sys.env.getOrElse("OAUTH_SECRET", "default-secret-change-me"),
    authorizeEndpoint = "https://auth.internal.corp/oauth2/authorize",
    tokenEndpoint = "https://auth.internal.corp/oauth2/token",
    allowedRedirectHosts = Set("monitoring.internal.corp", "logs.internal.corp", "metrics.internal.corp")
  )

  def normalizeUri(raw: String): URI = {
    val decoded = URLDecoder.decode(raw, StandardCharsets.UTF_8.name())
    new URI(decoded).normalize()
  }

  def extractEffectiveHost(uri: URI): String = {
    val host = Option(uri.getHost).getOrElse("")
    // Strip port if present in authority
    val authority = Option(uri.getAuthority).getOrElse(host)
    // Handle userinfo@host pattern by extracting host portion
    val effectiveHost = if (authority.contains("@")) {
      authority.split("@").last.split(":").head
    } else {
      authority.split(":").head
    }
    effectiveHost.toLowerCase
  }

  def validateRedirectUri(redirectUri: String): Boolean = {
    try {
      val uri = normalizeUri(redirectUri)
      val scheme = Option(uri.getScheme).getOrElse("").toLowerCase
      if (scheme != "https") return false

      val effectiveHost = extractEffectiveHost(uri)

      // Check if the effective host ends with any allowed host
      // This supports subdomains like "app.monitoring.internal.corp"
      config.allowedRedirectHosts.exists(allowed => 
        effectiveHost == allowed || effectiveHost.endsWith("." + allowed)
      )
    } catch {
      case _: Exception => false
    }
  }

  def computeStateHmac(state: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(config.clientSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256")
    mac.init(keySpec)
    Base64.getUrlEncoder.withoutPadding.encodeToString(mac.doFinal(state.getBytes(StandardCharsets.UTF_8)))
  }

  def handleOAuthCallback(code: String, state: String, redirectUri: String): Either[String, OAuthSession] = {
    if (shutdownRequested.get()) {
      return Left("Agent is shutting down, rejecting new auth flows")
    }

    // Validate state parameter HMAC
    val stateParts = state.split("\\.", 2)
    if (stateParts.length != 2) return Left("Invalid state format")
    val (statePayload, stateSignature) = (stateParts(0), stateParts(1))
    val expectedSig = computeStateHmac(statePayload)
    if (!java.security.MessageDigest.isEqual(expectedSig.getBytes, stateSignature.getBytes)) {
      return Left("State validation failed")
    }

    // Validate redirect URI
    if (!validateRedirectUri(redirectUri)) {
      return Left(s"Redirect URI not allowed: $redirectUri")
    }

    // In production, exchange code for token here
    val session = OAuthSession(
      accessToken = s"token_for_$code",
      redirectUri = redirectUri,
      state = statePayload,
      expiresAt = System.currentTimeMillis() + 3600000
    )
    currentSession.set(session)
    Right(session)
  }

  def initiateOAuthFlow(redirectUri: String): Either[String, String] = {
    if (!validateRedirectUri(redirectUri)) {
      return Left(s"Invalid redirect URI: $redirectUri")
    }

    val statePayload = java.util.UUID.randomUUID().toString
    val stateSigned = statePayload + "." + computeStateHmac(statePayload)

    val authUrl = s"${config.authorizeEndpoint}?" +
      s"client_id=${config.clientId}&" +
      s"redirect_uri=${java.net.URLEncoder.encode(redirectUri, "UTF-8")}&" +
      s"state=$stateSigned&" +
      s"response_type=code&" +
      s"scope=monitoring.read+monitoring.write"

    Right(authUrl)
  }

  def gracefulShutdown(): Unit = {
    shutdownRequested.set(true)
    // Allow in-flight requests to complete
    executor.shutdown()
    if (!executor.awaitTermination(30, TimeUnit.SECONDS)) {
      executor.shutdownNow()
    }
    currentSession.set(null)
    shutdownLatch.countDown()
  }

  def isHealthy: Boolean = !shutdownRequested.get() && currentSession.get() != null

  def main(args: Array[String]): Unit = {
    Runtime.getRuntime.addShutdownHook(new Thread(() => gracefulShutdown()))
    println("Monitoring agent started")
    shutdownLatch.await()
    println("Monitoring agent stopped")
  }
}
